//! Dynamic-programming optimizer core.
//!
//! Responsibility (`PLAN.md` §2 and §6): own the DP solver and everything that keeps it honest.
//!
//! * The numeric core of the old add-on's CPython extension (`optimize/_core.c`) is vendored
//!   verbatim in `csrc/core_solver.c` -- generated by `scripts/extract_core.py` from pinned line
//!   ranges -- and compiled with the old flags (`-O3 -ffp-contract=off -fno-fast-math`).  It stays
//!   the single source of an optimisation result, and `csrc/energy_opt_ffi.c` exposes it as a
//!   plain C ABI (the CPython glue is not vendored).
//! * [`dp`] is the safe Rust wrapper: [`solve`](dp::solve) / [`solve_with_terminal_row`](dp::solve_with_terminal_row)
//!   mirror the old `solve(pv, load, buy, sell, minutes, config[, terminal_row]) -> dict` call.
//! * [`validate`] owns input validation and post-solve verification: finiteness, the re-derived
//!   state grid, bounds, the SoC path, the objective and cycle cost, per-slot argmin equality and a
//!   sampled backward Bellman pass.  A plan that fails any check is refused, never "used because
//!   it is only slightly wrong".
//! * [`oracle`] holds a deliberately naive Rust DP used for the differential checks.
//!
//! The build embeds a digest of the C sources into the artifact; [`dp::verify_core_build`] compares
//! it with the sources this binary shipped, so a stale object file cannot run.
//!
//! Everything here is synchronous and allocation-light: a solve happens every 15 minutes on a
//! 120-slot horizon and stays well under the 50 ms budget (`tests/bench.rs` pins that).

pub mod config;
pub mod dp;
pub mod error;
pub mod oracle;
pub mod validate;

mod ffi;
mod sha256;

pub use config::{BatterySpec, Config, PvChargePreference};
pub use dp::{
    SolveInput, SolveResult, Window, core_build_sha, solve, solve_with_terminal_row,
    verify_core_build,
};
pub use error::{ConfigError, InputError, SolveError, ValidationError};
pub use ffi::EO_MAX_SLOTS;

/// The upstream add-on release the C core was extracted from.
pub const CORE_VERSION: &str = "ha-energy-manager 0.38.8";

/// The SHA-256 prefix (16 hex) of the C sources the artifact was compiled from.
///
/// Compiled into the C object as `-DCORE_BUILD_SHA` and re-checked at runtime.
pub const CORE_BUILD_SHA: &str = env!("EO_CORE_BUILD_SHA");

/// The full SHA-256 of the framed C sources this binary was built from.
pub const CORE_SOURCE_SHA256: &str = env!("EO_CORE_SOURCE_SHA256");
